package org.joda.time;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import org.joda.time.base.AbstractPartial;
import org.joda.time.field.AbstractPartialFieldProperty;
import org.joda.time.field.DateTimeFieldType;
import org.joda.time.field.DurationFieldType;
import org.joda.time.field.FieldUtils;
import org.joda.time.field.impl.DurationIsoField;
import org.joda.time.field.impl.MillisDurationField;
import org.joda.time.field.impl.SecondsDurationField;
import org.joda.time.field.impl.YearsDurationField;
import org.joda.time.format.DateTimeFormat;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Partial_with_TriageGen2Test {

    @Test(expected = IllegalArgumentException.class)
    public void testWith_NullFieldType_ThrowsException() {
        Partial partial = new Partial(ISOChronology.getInstance());
        partial.with(null, 1);
    }

    @Test
    public void testWith_ExistingField_SameValue_ReturnsThis() {
        DateTimeFieldType yearType = YearsDurationField.INSTANCE;
        Partial partial = new Partial(new DateTimeFieldType[]{yearType}, new int[]{2020}, ISOChronology.getInstance());

        Partial result = partial.with(yearType, 2020);

        assertSame("Should return the same instance if value is unchanged", partial, result);
    }

    @Test
    public void testWith_ExistingField_DifferentValue_ReturnsNewPartial() {
        DateTimeFieldType yearType = YearsDurationField.INSTANCE;
        Partial partial = new Partial(new DateTimeFieldType[]{yearType}, new int[]{2020}, ISOChronology.getInstance());

        Partial result = partial.with(yearType, 2021);

        assertNotSame(partial, result);
        assertEquals(2021, result.getValue(0));
        assertEquals(1, result.size());
    }

    @Test
    public void testWith_NewField_InsertAtBeginning_LargeUnit() {
        // Years is a large unit (large duration), should come first in sorted order (largest-smallest)
        // Note: The logic in the code: if (compare > 0) break; 
        // This means if the new field's unit is LARGER than the current field, it breaks and inserts.

        DateTimeFieldType yearType = YearsDurationField.INSTANCE; // Large unit
        DateTimeFieldType monthType = org.joda.time.field.impl.MonthsDurationField.INSTANCE; // Smaller unit

        Partial partial = new Partial(new DateTimeFieldType[]{monthType}, new int[]{1}, ISOChronology.getInstance());

        Partial result = partial.with(yearType, 2023);

        assertEquals(2, result.size());
        // Based on logic: Year should be index 0 because Year unit > Month unit
        assertEquals(yearType, result.getFieldType(0));
        assertEquals(2023, result.getValue(0));
        assertEquals(monthType, result.getFieldType(1));
        assertEquals(1, result.getValue(1));
    }

    @Test
    public void testWith_NewField_InsertInMiddle_SameUnitDifferentRange() {
        // Testing the compare == 0 branch (same duration, different range)
        // We need two types with same duration but different range durations. 
        // In Joda, this is rare for standard fields, but we can simulate via logic.
        // Since we can't easily mock DateTimeFieldType without complex setup, 
        // we rely on the existing field order logic.

        DateTimeFieldType type1 = org.joda.time.field.impl.SecondsDurationField.INSTANCE;
        DateTimeFieldType type2 = org.joda.time.field.impl.MillisDurationField.INSTANCE;

        Partial partial = new Partial(new DateTimeFieldType[]{type2}, new int[]{500}, ISOChronology.getInstance());
        Partial result = partial.with(type1, 10);

        assertEquals(2, result.size());
        assertEquals(type1, result.getFieldType(0));
        assertEquals(type2, result.getFieldType(1));
    }

    @Test
    public void testWith_NewField_UnitNotSupported() {
        // If unitField.isSupported() is false, loop 'i' remains 0
        // This tests the branch where the loop is bypassed or the condition is not met

        // We use a custom chronology or a field that might not be supported by a specific chrono
        // But for standard ISO, most are supported. 
        // We can trigger the 'i=0' by providing a field where isSupported is false.

        DateTimeFieldType unsupportedType = new DateTimeFieldType(
                DurationIsoField.INSTANCE.getField(ISOChronology.getInstance()), 
                DurationIsoField.INSTANCE.getField(ISOChronology.getInstance()), 
                "unsupported", 
                new org.joda.time.field.impl.impl.DurationFieldImpl(0, 0) {
                    @Override public boolean isSupported() { return false; }
                });

        Partial partial = new Partial(ISOChronology.getInstance());
        Partial result = partial.with(unsupportedType, 100);

        assertEquals(1, result.size());
        assertEquals(unsupportedType, result.getFieldType(0));
        assertEquals(100, result.getValue(0));
    }

    @Test
    public void testWith_NewField_InsertAtEnd() {
        DateTimeFieldType yearType = YearsDurationField.INSTANCE;
        DateTimeFieldType monthType = org.joda.time.field.impl.MonthsDurationField.INSTANCE;
        DateTimeFieldType dayType = org.joda.time.field.impl.DaysDurationField.INSTANCE;

        Partial partial = new Partial(new DateTimeFieldType[]{yearType, monthType}, new int[]{2020, 1}, ISOChronology.getInstance());

        // Day is smaller unit than month, so it should go at the end
        Partial result = partial.with(dayType, 15);

        assertEquals(3, result.size());
        assertEquals(yearType, result.getFieldType(0));
        assertEquals(monthType, result.getFieldType(1));
        assertEquals(dayType, result.getFieldType(2));
        assertEquals(15, result.getValue(2));
    }
}
